package com.autocare.platform.order;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.http.MediaType;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"JWT_SECRET=test-only-secret-with-at-least-32-characters","WECHAT_APP_ID=test-app"}) @AutoConfigureMockMvc class HealthDashboardHttpTest {
 @Autowired MockMvc mvc;@MockitoBean JwtDecoder decoder;@MockitoBean HealthPolicies policies;@MockitoBean HealthDashboard service;
 @BeforeEach void token(){when(decoder.decode(anyString())).thenAnswer(call->{String t=call.getArgument(0);return Jwt.withTokenValue(t).header("alg","HS256").subject("1").claim("subject_type",t.equals("owner")?"user":"operator_account").claim("role",t.equals("owner")?"OWNER":"OPERATOR").claim("app_id",t.equals("owner")?"test-app":"operator-account").claim("jti","session").expiresAt(Instant.now().plusSeconds(600)).build();});}
 @Test void separateRolesAndNoStore()throws Exception{mvc.perform(get("/api/vehicle/1/health-dashboard")).andExpect(status().isUnauthorized());mvc.perform(get("/api/vehicle/1/health-dashboard").header("Authorization","Bearer operator")).andExpect(status().isForbidden());mvc.perform(get("/api/admin/health-policies/1/OIL").header("Authorization","Bearer owner")).andExpect(status().isForbidden());when(service.read(any(),eq(1L))).thenReturn(Map.of("metrics",List.of()));mvc.perform(get("/api/vehicle/1/health-dashboard").header("Authorization","Bearer owner")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.metrics").isArray());}
 @Test void strictConfirmationAndPreferenceBodiesAndQuery()throws Exception{String valid="{\"expected_revision\":0,\"confirmed\":true,\"observation_revision\":1,\"policy_version\":1}";for(String b:List.of("null",valid+"{}",valid.replace(":true",":\"true\""),valid.replace("\"policy_version\":1","\"policy_version\":1,\"policy_version\":2"),valid.replace("\"expected_revision\":0","\"expected_revision\":-1")))mvc.perform(put("/api/vehicle/1/health/OIL/confirmation").header("Authorization","Bearer owner").header("Idempotency-Key",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isBadRequest());mvc.perform(get("/api/vehicle/1/health-dashboard?user_id=1").header("Authorization","Bearer owner")).andExpect(status().isBadRequest());mvc.perform(put("/api/vehicle/1/reminder-preference").header("Authorization","Bearer owner").header("Idempotency-Key",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).content("{\"expected_revision\":0,\"maintenance_days\":366,\"maintenance_km\":0,\"insurance_days\":0,\"inspection_days\":0}")).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void strictRuleMetricAndUuidBeforeService()throws Exception{for(String b:List.of("null","{\"expected_version\":0,\"rule\":null,\"extra\":1}","{\"expected_version\":0,\"rule\":{}}"))mvc.perform(put("/api/admin/health-policies/1/OIL").header("Authorization","Bearer operator").header("Idempotency-Key",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isBadRequest());mvc.perform(get("/api/admin/health-policies/1/FAKE").header("Authorization","Bearer operator")).andExpect(status().isBadRequest());mvc.perform(put("/api/admin/health-policies/1/OIL").header("Authorization","Bearer operator").contentType(MediaType.APPLICATION_JSON).content("{\"expected_version\":0,\"rule\":null}")).andExpect(status().isBadRequest());verifyNoInteractions(policies);}
 @Test void databaseFailureDoesNotExposeSql()throws Exception{when(service.read(any(),anyLong())).thenThrow(new org.springframework.dao.DataAccessResourceFailureException("private SQL"));mvc.perform(get("/api/vehicle/1/health-dashboard").header("Authorization","Bearer owner")).andExpect(status().isServiceUnavailable()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.message").value("健康来源服务暂不可用，请稍后重试"));}
 @Test void directorySearchStrictBodyAndOwnerOnly()throws Exception{for(String b:List.of("null","{\"query\":\" \",\"category\":0,\"page\":1}","{\"query\":\"term\",\"category\":7,\"page\":1}","{\"query\":\"term\",\"category\":0,\"page\":1,\"query\":\"other\"}"))mvc.perform(post("/api/service/project-search").header("Authorization","Bearer owner").contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isBadRequest());mvc.perform(post("/api/service/project-search").header("Authorization","Bearer operator").contentType(MediaType.APPLICATION_JSON).content("{\"query\":\"term\",\"category\":0,\"page\":1}")).andExpect(status().isForbidden());}
}
